    extracted_claims = parse_atomic_claims(draft.content)
    # Never let an LLM self-certify claims; require deterministic alignment to verified evidence
    unsubstantiated = [c for c in extracted_claims if not approved_claim_graph.entails(c)]
    if unsubstantiated:
        return Route.LEGAL_REVIEW(reasons=unsubstantiated) # Hard stop: models cannot assume regulatory liability
    # Ad networks strip C2PA metadata, so disclosure must be burned directly into the asset payload
    disclosed_asset = burn_disclosure_into_render(draft.content, draft.target_jurisdiction)
    # Surface checkers flag colors, not meaning; score semantic drift against cleared anchor creative
    drift_score = measure_latent_delta(disclosed_asset, draft.anchor_creative)
